package search

import (
	"testing"

	"voke/internal/logic/appsmodel"
)

// TestAppAlias 钉死「ID → 英文文件名词干」的规则：已知文件夹相对路径取末段去扩展名；
// AUMID（含 `!`）/ AutoGenerated 占位 / 纯 GUID 段没有可用英文名。
func TestAppAlias(t *testing.T) {
	cases := []struct{ id, want string }{
		{`{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\services.msc`, "services"},
		{`{F38BF404-1D43-42F2-9305-67DE0B28FC23}\regedit.exe`, "regedit"},
		{`Microsoft.AutoGenerated.{5E8FC15D-96C5-8C7D-B1AF-2757B67E4C6D}`, ""},
		{`Microsoft.WindowsCalculator_8wekyb3d8bbwe!App`, ""},
		{`{GUID}`, ""},
		{``, ""},
	}
	for _, c := range cases {
		if got := appAlias(c.id); got != c.want {
			t.Errorf("appAlias(%q) = %q，想要 %q", c.id, got, c.want)
		}
	}
}

// TestFilterAppsEnglishFilenameAlias：本地化显示名（服务 / 注册表编辑器）也能按英文
// 程序名（service / regedit）搜到——靠条目 ID 里的文件名兜底。中文/拼音仍可。
// 反例：任务管理器的 ID 是 AutoGenerated（无英文名），故 task 仍搜不到（与 Rust 的
// .lnk 枚举差异，见 PoC 文档）。
func TestFilterAppsEnglishFilenameAlias(t *testing.T) {
	apps := []appsmodel.AppEntry{
		{Name: "服务", Path: `shell:AppsFolder\{1AC14E77}\services.msc`, ID: `{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\services.msc`},
		{Name: "注册表编辑器", Path: `shell:AppsFolder\{F38BF404}\regedit.exe`, ID: `{F38BF404-1D43-42F2-9305-67DE0B28FC23}\regedit.exe`},
		{Name: "任务管理器", Path: `shell:AppsFolder\Microsoft.AutoGenerated.{GUID}`, ID: `Microsoft.AutoGenerated.{5E8FC15D-96C5-8C7D-B1AF-2757B67E4C6D}`},
		{Name: "Chrome", Path: `shell:AppsFolder\Chrome`, ID: "Chrome"},
	}
	only := func(q, want string) {
		t.Helper()
		got := FilterApps(q, apps, nil)
		if len(got) != 1 || got[0].Name != want {
			t.Errorf("FilterApps(%q) = %+v，想要唯一命中 %q", q, got, want)
		}
	}
	only("service", "服务")
	only("regedit", "注册表编辑器")
	only("fw", "服务") // 拼音 initials 仍可用
	if got := FilterApps("task", apps, nil); len(got) != 0 {
		t.Errorf("task 不应命中（AutoGenerated 无英文名）：%+v", got)
	}
}
